func isDryRun(raw string) bool {
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case "true", "1":
		return true
	default:
		return false
	}
}

func maskHomeserverURL(raw string) string {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return "<unset>"
	}
	u, err := url.Parse(raw)
	if err != nil || u.Scheme == "" || u.Host == "" {
		return "***"
	}
	if u.User != nil {
		u.User = url.UserPassword(u.User.Username(), "***")
	}
	if u.RawQuery != "" {
		q := u.Query()
		for k := range q {
			q.Set(k, "***")
		}
		u.RawQuery = q.Encode()
	}
	u.Fragment = ""
	return strings.TrimRight(strings.ReplaceAll(u.String(), "%2A", "*"), "/")
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if value != "" {
			return value
		}
	}
	return ""
}

func parseMaxRetries(value string) (int, error) {
	if value == "" {
		return plugin.DefaultMaxRetries, nil
	}
	maxRetries, err := strconv.Atoi(value)
	if err != nil || maxRetries < 0 {
		return 0, fmt.Errorf("SEMREL_PLUGIN_MAX_RETRIES must be a non-negative integer")
	}
	return maxRetries, nil
}

func parseRetryDelay(value string) (time.Duration, error) {
	if value == "" {
		return plugin.DefaultRetryDelay, nil
	}
	delay, err := time.ParseDuration(value)
	if err != nil || delay < 0 {
		return 0, fmt.Errorf("SEMREL_PLUGIN_RETRY_DELAY must be a non-negative duration")
	}
	return delay, nil
}
